message.content:
{
  "hypotheses": [
    {
      "team": "home",
      "reasons": [
        {
          "text": "Son Heung-min이 차범근과 함께 58골 공동 1위에 있어 이 경기 한 골로 단독 1위가 되는 동기가 걸려 있다.",
          "var_ids": ["R2"]
        },
        {
          "text": "한국은 우즈베키스탄전에서 Son의 최다 득점 단독 1위 달성이라는 명확한 목표를 안고 경기에 들어간다.",
          "var_ids": ["R4"]
        },
        {
          "text": "9월 두 경기에서 4-4-2로 1-1에 그친 뒤라 이번 경기에서 전술이나 선수 구성 변화가 나올 수 있다.",
          "var_ids": ["R5"]
        }
      ],
      "breaks": [
        {
          "text": "Kim Min-jae가 이번 우즈베키스탄전에 나서기 어려워 수비 중심축이 빠진다.",
          "var_ids": ["R1"]
        },
        {
          "text": "8일 안에 이번이 세 번째 경기로 일정 과부하가 걸려 있다.",
          "var_ids": ["IR11-home"]
        },
        {
          "text": "최근 5경기에서 득점이 0.8골대에 머물러 공격 생산이 다시 막힐 수 있다.",
          "var_ids": ["R5"]
        }
      ]
    },
    {
      "team": "away",
      "reasons": [
        {
          "text": "한국의 Kim Min-jae 결장 가능성과 8일 3경기 일정 과부하가 우즈베키스탄에게 중원과 뒷공간을 열어준다.",
          "var_ids": ["R1", "IR11-home"]
        },
        {
          "text": "최근 5경기에서 경기당 1.8골(보정 1.25)을 넣으며 3경기 연속 득점 중이라 득점 흐름이 이어지고 있다.",
          "var_ids": ["S01-away"]
        }
      ],
      "breaks": [
        {
          "text": "최근 5경기에서 3패를 포함해 수비가 흔들렸고 실점이 크게 나왔다.",
          "var_ids": ["S01-away"]
        },
        {
          "text": "한국은 Son의 최다 득점 단독 1위 도전이라는 동기로 공격에 힘을 싣는다.",
          "var_ids": ["R2", "R4"]
        },
        {
          "text": "한국이 9월 두 경기 부진 뒤 전술과 선수 구성을 바꿔 나올 수 있다.",
          "var_ids": ["R5"]
        }
      ]
    }
  ],
  "scenarios": [
    {
      "id": "대량득점형",
      "outcomes": [[2, 2], [3, 2]],
      "driver_vars": ["R1", "S01-away", "R2"],
      "mechanism": "Kim Min-jae 결장 가능성으로 한국의 수비 중심이 흔들리고, 최근 경기당 1.8골을 넣는 우즈베키스탄의 득점 흐름과 Son의 기록 도전에 따른 한국의 전진이 맞물려 양쪽 모두 실점이 나온다."
    },
    {
      "id": "우세팀_실점_동반형",
      "outcomes": [[3, 1], [2, 1]],
      "driver_vars": ["R4", "R2", "R1"],
      "mechanism": "한국이 Son의 단독 1위 달성을 위해 공격적으로 밀어붙여 득점을 쌓지만, 수비 중심이 빠진 상태라 우즈베키스탄의 반격에 한 골을 내준다."
    },
    {
      "id": "핸디_대응형",
      "outcomes": [[1, 0], [2, 1]],
      "driver_vars": ["IR11-home", "R5"],
      "mechanism": "8일 안에 세 번째 경기를 치르는 일정 과부하와 9월 두 경기 부진 뒤의 전술·선수 구성 변화로 한국의 경기력이 무거워져 한 골 차 승부에 그친다."
    },
    {
      "id": "회귀_반전형",
      "outcomes": [[0, 1], [1, 2]],
      "driver_vars": ["R5", "IR11-home", "S01-away"],
      "mechanism": "한국이 최근 5경기 0.8골대의 낮은 득점 생산과 일정 과부하 속에서 전술 재정비에 시간을 쓰는 사이, 득점 흐름이 살아 있는 우즈베키스탄이 역습으로 앞서간다."
    },
    {
      "id": "결장_공백_원정형",
      "outcomes": [[0, 2], [1, 2]],
      "driver_vars": ["R1", "IR11-home"],
      "mechanism": "수비 중심축의 결장 가능성과 누적된 일정 과부하가 겹쳐 한국이 전후반에 걸쳐 조직적으로 밀리며 실점을 허용한다."
    }
  ]
}
